# Generated by manage.py generate_test_cases.
import json
from typing import Any

from django.http import HttpResponse

from bloomerp.forms.document_signing.send_signature_request import SendSignatureRequestForm
from bloomerp.models import EmailAccount, User
from bloomerp.models.document_signing import SignatureLayoutRole
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.models.document_signing.support import SigningFixturesMixin


class TestSendSignatureRequestComponent(SigningFixturesMixin, BloomerpComponentTestCase):
    """Cover the read-only composer and recipient-dependent email validation."""

    view_name = 'components_document_signing_send_signature_request'
    auto_create_customers = False

    def setUp(self) -> None:
        """Prepare an authorized PDF, signing role, active sender, and internal identities."""
        super().setUp()
        self.account = EmailAccount.objects.create(
            name="Sender", email_address="sender@example.com", status=EmailAccount.Status.ACTIVE
        )
        self.no_email_user = User.objects.create(username="email-free-signer", email="")
        self.inactive_user = User.objects.create(
            username="inactive-signer", email="inactive@example.com", is_active=False
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        kwargs = {"file_id": str(self.original.pk)}
        query = {"layout_id": str(self.layout.pk)}
        return [
            RequestScenario(
                name="Composer requires authentication", view_kwargs=kwargs,
                query_params=query, expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Composer renders user lookup and the optional email controls",
                user=self.admin_user, view_kwargs=kwargs, query_params=query,
                expected=ExpectedResult(response_validators=self.composer_form),
            ),
            RequestScenario(
                name="A no-policy user cannot read an arbitrary signing document",
                user=self.normal_user, view_kwargs=kwargs, query_params=query,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Composer rejects ambiguous source identifiers", user=self.admin_user,
                view_kwargs=kwargs, query_params={**query, "preparation_id": str(self.layout.pk)},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Composer validates recipients and submission metadata before dispatch", method="POST",
                user=self.admin_user, view_kwargs=kwargs, data=query,
                expected=ExpectedResult(status_code=400),
            ),
        ]

    def composer_form(self, response: HttpResponse) -> bool:
        """Check the actual form supplies the shared identity picker and a borderless editor hint."""
        form = response.context["form"]
        html = response.content.decode()
        return (
            'bloomerp-component="bloomerp:send-signature-request"' in html
            and "data-recipient-users" in html
            and "data-send-email" in html
            and "Write an optional message" in html
            and form.fields["content"].widget.attrs["has_border"] is False
        )

    def test_recipient_delivery_validation(self) -> None:
        """Require external email and reject forged, unreadable, or mismatched user identities."""
        internal = {
            "recipient_party_a": self.normal_user.email,
            "recipient_users_party_a": json.dumps([str(self.normal_user.pk)]),
        }
        cases: list[tuple[str, User, dict[str, Any], str | None, bool]] = [
            ("external cannot opt out", self.admin_user, {
                "recipient_party_a": "guest@example.com", "sender": str(self.account.pk),
            }, None, True),
            ("external requires sender", self.admin_user, {
                "recipient_party_a": "guest@example.com",
            }, "sender", True),
            ("internal can skip email and sender", self.admin_user, internal, None, False),
            ("internal can request email", self.admin_user, {
                **internal, "send_email": "on", "sender": str(self.account.pk),
            }, None, True),
            ("internal sending requires sender", self.admin_user, {
                **internal, "send_email": "on",
            }, "sender", True),
            ("typed account address stays external", self.admin_user, {
                "recipient_party_a": self.normal_user.email,
            }, "sender", True),
            ("one address per role", self.admin_user, {
                "recipient_party_a": "first@example.com, second@example.com",
            }, "recipient_party_a", False),
            ("forged identity cannot hide an external address", self.admin_user, {
                **internal, "recipient_party_a": "external@example.com",
            }, "recipient_party_a", False),
            ("unknown account rejected", self.admin_user, {
                **internal, "recipient_users_party_a": '["missing"]',
            }, "recipient_party_a", False),
            ("inactive account rejected", self.admin_user, {
                "recipient_party_a": self.inactive_user.email,
                "recipient_users_party_a": json.dumps([str(self.inactive_user.pk)]),
            }, "recipient_party_a", False),
            ("unreadable account rejected", self.normal_user, internal, "recipient_party_a", False),
            ("email-free internal delivery", self.admin_user, {
                "recipient_users_party_a": json.dumps([str(self.no_email_user.pk)]),
            }, None, False),
            ("email-free account cannot receive email", self.admin_user, {
                "recipient_users_party_a": json.dumps([str(self.no_email_user.pk)]),
                "send_email": "on", "sender": str(self.account.pk),
            }, "recipient_party_a", True),
            ("empty role rejected", self.admin_user, {}, "recipient_party_a", False),
            ("malformed identity payload rejected", self.admin_user, {
                "recipient_users_party_a": '{"id": "forged"}',
            }, "recipient_party_a", False),
        ]
        for name, actor, data, error, send_email in cases:
            with self.subTest(name=name):
                form = SendSignatureRequestForm(user=actor, roles=[self.role], data=data)
                self.assertEqual(form.is_valid(), error is None, form.errors)
                if error is not None:
                    self.assertIn(error, form.errors)
                self.assertEqual(form.cleaned_data["send_email"], send_email)

    def test_mixed_recipients_require_email(self) -> None:
        """An external signer among multiple internal roles must keep email enabled."""
        other = SignatureLayoutRole.objects.create(layout=self.layout, key="other", label="Other")
        form = SendSignatureRequestForm(user=self.admin_user, roles=[self.role, other], data={
            "recipient_party_a": self.normal_user.email,
            "recipient_users_party_a": json.dumps([str(self.normal_user.pk)]),
            "recipient_other": "outside@example.com", "sender": str(self.account.pk),
        })
        self.assertTrue(form.is_valid(), form.errors)
        self.assertTrue(form.cleaned_data["send_email"])
